import java.nio.file.Path;
import java.util.Map;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.core.env.MapPropertySource;
import org.springframework.beans.factory.config.DependencyDescriptor;
import org.springframework.boot.jackson.autoconfigure.JacksonAutoConfiguration;
import tools.jackson.databind.ObjectMapper;
import ai.neargo.shop.trade.service.impl.OrderServiceImpl;
import ai.neargo.shop.trade.order.service.create.CounterEconomicCompatibilityTest;
public class ReproduceCounterGolden {
  public static void main(String[] args) throws Exception {
    try (var context = new AnnotationConfigApplicationContext()) {
      context.getEnvironment().getPropertySources().addFirst(new MapPropertySource("application-jackson", Map.of(
          "spring.jackson.deserialization.accept-float-as-int", "false")));
      context.register(JacksonAutoConfiguration.class);
      context.refresh();
      var application = context.getBean(ObjectMapper.class);
      var legacy = (ObjectMapper) context.getBeanFactory().resolveDependency(new DependencyDescriptor(
          OrderServiceImpl.class.getDeclaredField("legacyCheckoutJson"), true), "orderServiceImpl");
      if (legacy != application) throw new IllegalStateException("application/legacy injection drift");
      System.out.println("APPLICATION_MAPPER=" + application.getClass().getName());
      System.out.println("LEGACY_INJECTION_SAME_BEAN=" + (legacy == application));
      System.out.println("ACCEPT_FLOAT_AS_INT=" + application.isEnabled(tools.jackson.databind.DeserializationFeature.ACCEPT_FLOAT_AS_INT));
      CounterEconomicCompatibilityTest.generateBaseline(application, legacy, Path.of(args[0]), Path.of(args[1]));
      CounterEconomicCompatibilityTest.verifyBaseline(application, legacy, Path.of(args[1]));
      System.out.println("GENUINE_OLD_GOLDEN_GENERATION_AND_COMPATIBILITY=PASS");
    }
  }
}
